import { Queue, Worker } from "bullmq";
import { config } from "../config";
import { connection } from "../redis";
import { cleanupExpiredInvites } from "./cleanup";

export const jobs = new Queue("garden-jobs", { connection });

export async function registerSchedules() {
  await jobs.upsertJobScheduler(
    "cleanup-invites",
    { pattern: "0 3 * * *", tz: config.gardenTimezone },
    { name: "cleanup-invites" },
  );
}

export function startWorker() {
  return new Worker(
    "garden-jobs",
    async (job) => {
      if (job.name === "cleanup-invites") return cleanupExpiredInvites();
    },
    { connection },
  );
}

