+import { config } from "../config";
+import { db } from "../db";
+import { sendEmail } from "../email";
+import { reminderEmail } from "../emails/reminder";
+
+// Runs at 18:00 garden time. Picks tomorrow's shifts that are not cancelled and
+// have no reminder yet. Each shift is stamped before its email goes out, so a
+// retry or a second run sends nothing twice.
+export async function sendWateringReminders() {
+  const { rows } = await db.query(
+    `SELECT s.id, s.starts_at, m.email, m.name
+       FROM shifts s JOIN members m ON m.id = s.member_id
+      WHERE s.cancelled_at IS NULL
+        AND s.reminder_sent_at IS NULL
+        AND (s.starts_at AT TIME ZONE $1)::date = (now() AT TIME ZONE $1)::date + 1`,
+    [config.gardenTimezone],
+  );
+  for (const shift of rows) {
+    const claimed = await db.query(
+      `UPDATE shifts SET reminder_sent_at = now()
+        WHERE id = $1 AND reminder_sent_at IS NULL RETURNING id`,
+      [shift.id],
+    );
+    if (claimed.rowCount === 1) await sendEmail(reminderEmail(shift));
+  }
+}

