+import { beforeEach, describe, expect, it } from "vitest";
+import { sendWateringReminders } from "../src/jobs/watering-reminders";
+import { outbox, resetDb, seedShift, tomorrowAt } from "./helpers";
+
+describe("sendWateringReminders", () => {
+  beforeEach(resetDb);
+
+  it("sends one email per shift tomorrow", async () => {
+    await seedShift({ member: "ines", startsAt: tomorrowAt("07:00") });
+    await seedShift({ member: "tomas", startsAt: tomorrowAt("19:30") });
+    await sendWateringReminders();
+    expect(outbox().map((m) => m.memberId)).toEqual(["ines", "tomas"]);
+  });
+
+  it("sends nothing on a second run", async () => {
+    await seedShift({ member: "ines", startsAt: tomorrowAt("07:00") });
+    await sendWateringReminders();
+    await sendWateringReminders();
+    expect(outbox()).toHaveLength(1);
+  });
+
+  it("skips cancelled shifts", async () => {
+    await seedShift({ member: "ines", startsAt: tomorrowAt("07:00"), cancelled: true });
+    await sendWateringReminders();
+    expect(outbox()).toHaveLength(0);
+  });
+});

