+import { db } from "./db";
+import { sendEmail } from "./email";
+
+export async function sendReminders() {
+  const { rows } = await db.query(
+    `SELECT s.id, s.starts_at, m.email, m.name FROM shifts s
+       JOIN members m ON m.id = s.member_id
+      WHERE s.starts_at::date = current_date + 1`,
+  );
+  for (const row of rows) {
+    await sendEmail({
+      to: row.email,
+      subject: "Watering shift tomorrow",
+      text: `Hi ${row.name}, you have a watering shift tomorrow at ${row.starts_at}.`,
+    });
+  }
+}
